import{_ as n,C as a,c as s,o as i,a3 as t,G as r}from"./chunks/framework.Dokpd4od.js";const v=JSON.parse('{"title":"Manage orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/quotations-orders/manage-orders.md","filePath":"master/sales/sales/quotations-orders/manage-orders.md","lastUpdated":1791902625000}'),l={name:"master/sales/sales/quotations-orders/manage-orders.md"};function d(g,e,h,c,m,u){const o=a("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="manage-orders" tabindex="-1">Manage orders <a class="header-anchor" href="#manage-orders" aria-label="Permalink to &quot;Manage orders&quot;">​</a></h1><p>An order is a quotation that the customer accepted. The Orders page lists every order, so you can see what is delivered, what is invoiced and what is still open. From an order you can create an invoice, lock it, or cancel it.</p><p>This page explains the list, the order page, the buttons, and how an order ends with an invoice and a payment.</p><blockquote><p><strong>In simple words:</strong> Orders are the quotations your customers said yes to. Use this page to follow them, invoice them and get paid.</p></blockquote><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>An order comes from a confirmed quotation. See <a href="./send-and-confirm-quotation.html">Send and confirm a quotation</a>. We use the same example here: order <strong>SO/1</strong> for Azure Interiors, with 5 Camping Hammocks and 10 Smart LED Desk Lamps. The total is $603.75.</p><h2 id="the-orders-list" tabindex="-1">The Orders list <a class="header-anchor" href="#the-orders-list" aria-label="Permalink to &quot;The Orders list&quot;">​</a></h2><p>Open <code>Sales → Orders → Orders</code>. Each row is one order.</p>',8)),r(o,{src:"/images1/sales/orders_list.png",alt:"Orders list with the tabs Default, My Orders, To Invoice, Up Selling and Archived"}),e[1]||(e[1]=t('<h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Number:</em></strong> The order number, for example <code>SO/1</code>.</li><li><strong><em>Creation Date:</em></strong> The day the record was created.</li><li><strong><em>Customer:</em></strong> Who ordered.</li><li><strong><em>Sales Person:</em></strong> The user who owns the order.</li><li><strong><em>Amount Total:</em></strong> The total with tax.</li><li><strong><em>Status:</em></strong> The state, for example <strong>Sales Order</strong> or <strong>Cancelled</strong>.</li></ul><p>More columns are hidden by default. Open the column toggle on the list to show them:</p><ul><li><strong><em>Delivery Status:</em></strong> How much has been delivered. The values are <strong>Nothing To Deliver</strong>, <strong>Pending</strong>, <strong>Started</strong>, <strong>Partially Delivered</strong> and <strong>Fully Delivered</strong>.</li><li><strong><em>Invoice Status:</em></strong> How much has been invoiced. The values are <strong>Nothing to Invoice</strong>, <strong>To Invoice</strong>, <strong>Fully Invoiced</strong> and <strong>Upselling Opportunity</strong>.</li><li><strong><em>Untaxed Amount</em></strong>, <strong><em>Amount Tax</em></strong>, <strong><em>Expected Date</em></strong>, <strong><em>Sales Team</em></strong> and <strong><em>Customer Reference</em></strong>.</li></ul><h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><p>The tabs above the list are saved filters:</p><ul><li><strong><em>Default:</em></strong> All orders.</li><li><strong><em>My Orders:</em></strong> Orders where you are the sales person.</li><li><strong><em>To Invoice:</em></strong> Orders with the invoice status <strong>To Invoice</strong>. Start here when you bill.</li><li><strong><em>Up Selling:</em></strong> Orders with the <strong>Upselling Opportunity</strong> invoice status. See <a href="./../invoicing/order-to-upsell.html">Sell more to the same customer</a>.</li><li><strong><em>Archived:</em></strong> Deleted orders.</li></ul><h3 id="search-group-and-filter" tabindex="-1">Search, group and filter <a class="header-anchor" href="#search-group-and-filter" aria-label="Permalink to &quot;Search, group and filter&quot;">​</a></h3><ul><li>Type in the search box to find an order.</li><li>Click <strong>Group by</strong> to group rows, for example by <strong>Customer</strong>, <strong>Sales Person</strong>, <strong>Sales Team</strong>, <strong>Currency</strong> or <strong>Company</strong>.</li><li>Click the filter button to filter by sales person, customer, payment term, currency and more.</li></ul><p>See <a href="./../../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Open the <strong>To Invoice</strong> view every morning. Every order in it is waiting for an invoice.</p></div><h2 id="open-an-order" tabindex="-1">Open an order <a class="header-anchor" href="#open-an-order" aria-label="Permalink to &quot;Open an order&quot;">​</a></h2><p>Click a row to open the order. The state bar shows <strong>Sales Order</strong>. The page has four tabs: <strong>View</strong>, <strong>Edit</strong>, <strong>Invoices</strong> and <strong>Deliveries</strong>.</p><h3 id="the-view-tab" tabindex="-1">The View tab <a class="header-anchor" href="#the-view-tab" aria-label="Permalink to &quot;The View tab&quot;">​</a></h3><p>The top part shows the <strong>Customer</strong>, <strong>Expiration</strong>, <strong>Quotation Date</strong> and <strong>Payment Term</strong>. Below it you find these sections:</p><ul><li><strong>Order Line:</strong> The products you sell.</li><li><strong>Other Information</strong> and <strong>Terms &amp; Conditions:</strong> Extra details of the order.</li></ul><p>The <strong>Order Line</strong> table has the usual columns: <strong>Product</strong>, <strong>Quantity</strong>, <strong>UOM</strong>, <strong>Unit Price</strong>, <strong>Taxes</strong> and <strong>Amount</strong>. A confirmed order adds two more:</p><ul><li><strong><em>Delivered:</em></strong> How many units were delivered to the customer.</li><li><strong><em>Invoiced:</em></strong> How many units were already invoiced.</li></ul><p>For SO/1, both columns start at 0. They grow as you deliver and invoice.</p><p>At the bottom you see the <strong>Untaxed Amount</strong>, <strong>Amount Tax</strong>, <strong>Amount Total</strong> and <strong>Margin</strong>.</p>',20)),r(o,{src:"/images1/sales/order_view_lines.png",alt:"Confirmed order with Delivered and Invoiced columns on the order lines"}),e[2]||(e[2]=t('<h3 id="the-edit-tab" tabindex="-1">The Edit tab <a class="header-anchor" href="#the-edit-tab" aria-label="Permalink to &quot;The Edit tab&quot;">​</a></h3><p>Click <strong>Edit</strong> to change the order. On this page the delivery and invoice columns are named <strong>Quantity Delivered</strong> and <strong>Quantity Invoiced</strong>.</p><p>Once an order is confirmed, the main fields and the order lines are read only. A locked order is read only too.</p><h2 id="buttons-on-an-order" tabindex="-1">Buttons on an order <a class="header-anchor" href="#buttons-on-an-order" aria-label="Permalink to &quot;Buttons on an order&quot;">​</a></h2><ul><li><strong><em>Cancel:</em></strong> Cancels the order. A window lets you email the customer at the same time.</li><li><strong><em>Create Invoice:</em></strong> Opens the <strong>Create Invoice</strong> window.</li><li><strong><em>Preview:</em></strong> Shows the document as the customer sees it.</li><li><strong><em>Lock</em></strong> / <strong><em>Unlock</em>:</strong> Locks the order, or opens it again.</li></ul><p><strong>Create Invoice</strong> only shows while the <strong>Invoice Status</strong> is <strong>To Invoice</strong>. <strong>Lock</strong> and <strong>Unlock</strong> only show on a confirmed order. <strong>Send By Email</strong> and <strong>Confirm</strong> no longer show, because the quotation stage is over.</p><p>To cancel an order, use the same window as for a quotation. See <a href="./send-and-confirm-quotation.html#cancel-a-quotation">Cancel a quotation</a>.</p><h3 id="set-an-order-back-to-a-quotation" tabindex="-1">Set an order back to a quotation <a class="header-anchor" href="#set-an-order-back-to-a-quotation" aria-label="Permalink to &quot;Set an order back to a quotation&quot;">​</a></h3><p>A cancelled order shows <strong>Set as Quotation</strong>. Click it to make the record a quotation again. The invoice status is reset to <strong>Nothing to Invoice</strong>.</p><h2 id="create-an-invoice" tabindex="-1">Create an invoice <a class="header-anchor" href="#create-an-invoice" aria-label="Permalink to &quot;Create an invoice&quot;">​</a></h2><p>An invoice is the bill you send to the customer. Create it from the order, so the lines and prices come across by themselves.</p><ol><li>Open the order.</li><li>Click <strong>Create Invoice</strong>.</li><li>In the <strong>Create Invoice</strong> window, keep <strong>Regular invoice</strong>. It is the only option.</li><li>Click <strong>Submit</strong>. Click <strong>Cancel</strong> to close the window without creating anything.</li></ol>',12)),r(o,{src:"/images1/sales/create_invoice_window.png",alt:"Create Invoice window with the Regular invoice option, Submit and Cancel buttons"}),e[3]||(e[3]=t('<p>Aureus creates a draft invoice for the quantities your invoicing policy allows. A policy can say &quot;invoice what was ordered&quot; or &quot;invoice what was delivered&quot;. See <a href="./../invoicing/invoicing-policies.html">Invoicing policies</a> and <a href="./../invoicing/order-to-invoice.html">Create an invoice from an order</a>.</p><p>If nothing can be invoiced yet, Aureus shows a warning and creates no invoice.</p><h2 id="invoices-tab" tabindex="-1">Invoices tab <a class="header-anchor" href="#invoices-tab" aria-label="Permalink to &quot;Invoices tab&quot;">​</a></h2><p>The <strong>Invoices</strong> tab lists every invoice made from this order. The number on the tab counts them. You can <strong>Export</strong> the list and use <strong>Group by</strong>.</p><ul><li><strong><em>Number:</em></strong> The invoice number.</li><li><strong><em>State:</em></strong> Whether the invoice is a draft, posted or cancelled.</li><li><strong><em>Created By:</em></strong> The user who made it.</li><li><strong><em>Customer:</em></strong> Who gets billed.</li><li><strong><em>Invoice Date</em></strong> and <strong><em>Due Date</em>:</strong> When it was issued and when it must be paid.</li><li><strong><em>Tax Excluded</em></strong>, <strong><em>Tax</em></strong> and <strong><em>Total</em>:</strong> The amounts.</li><li><strong><em>Amount Due:</em></strong> How much the customer still owes.</li><li><strong><em>Payment State:</em></strong> Whether the invoice is paid.</li></ul><p>Click an invoice to open it. For SO/1, expect one row with a total of $603.75.</p>',6)),r(o,{src:"/images1/sales/order_invoices_tab.png",alt:"Invoices tab of an order with a draft invoice, Amount Due and Payment State Not paid"}),e[4]||(e[4]=t('<p>A new invoice starts as <strong>Draft</strong> with a <strong>Payment State</strong> of <strong>Not paid</strong>. The <strong>Amount Due</strong> equals the <strong>Total</strong> until a payment is recorded.</p><h2 id="deliveries-tab" tabindex="-1">Deliveries tab <a class="header-anchor" href="#deliveries-tab" aria-label="Permalink to &quot;Deliveries tab&quot;">​</a></h2><p>This tab only shows when the Inventories plugin is installed. It lists the stock moves that send the goods to the customer. The number on the tab counts them.</p><ul><li><strong><em>Favorite:</em></strong> Marks a delivery you want to keep in view.</li><li><strong><em>Reference:</em></strong> The delivery number, for example <code>WH/OUT/42</code>.</li><li><strong><em>Contact:</em></strong> The customer.</li><li><strong><em>Scheduled At:</em></strong> The planned date.</li><li><strong><em>Source Document:</em></strong> The order that asked for the delivery, for example <code>SO/3</code>.</li><li><strong><em>Company:</em></strong> The company that ships.</li><li><strong><em>State:</em></strong> For example <strong>Done</strong>.</li></ul><p>An order can have more than one row, for example a pick, a pack and an out delivery. When they are all <strong>Done</strong>, the <strong>Delivery Status</strong> is <strong>Fully Delivered</strong> and the <strong>Delivered</strong> column is filled.</p>',5)),r(o,{src:"/images1/sales/order_deliveries_tab.png",alt:"Deliveries tab of an order"}),e[5]||(e[5]=t('<h2 id="payment" tabindex="-1">Payment <a class="header-anchor" href="#payment" aria-label="Permalink to &quot;Payment&quot;">​</a></h2><p>Payment is the last step. Aureus does not take money on the order. You record it on the invoice. Here is the path from order to cash.</p><ol><li><strong>Payment Term.</strong> On the order, the <strong>Payment Term</strong> field says when the customer must pay, for example <strong>Immediate Payment</strong>. The invoice copies this term to work out its <strong>Due Date</strong>. You set it when you <a href="./create-quotation.html">create the quotation</a>.</li><li><strong>Create the invoice.</strong> Click <strong>Create Invoice</strong> on the order, as shown above.</li><li><strong>Post the invoice.</strong> Open it from the <strong>Invoices</strong> tab and confirm it. See <a href="./../../../finance/customer-invoices/create-invoice.html">Create an invoice</a>.</li><li><strong>Register the payment.</strong> When the money arrives, open the invoice and register it. See <a href="./../../../finance/payments/register-payment.html">Register a payment</a>.</li></ol><p>After the payment, look at the <strong>Invoices</strong> tab again. The <strong>Amount Due</strong> goes down. When it reaches 0, the <strong>Payment State</strong> shows the invoice as paid.</p><p>For SO/1, the <strong>Amount Due</strong> starts at $603.75. A full payment of $603.75 brings it to $0.00.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Part payments work too. The <strong>Amount Due</strong> shows what is left until the invoice is paid in full.</p></div><h2 id="lock-an-order" tabindex="-1">Lock an order <a class="header-anchor" href="#lock-an-order" aria-label="Permalink to &quot;Lock an order&quot;">​</a></h2><p>Lock stops people from changing a confirmed order by mistake.</p><ol><li>Open a confirmed order.</li><li>Click <strong>Lock</strong>. The button now reads <strong>Unlock</strong>, and the order lines can no longer be edited.</li><li>Click <strong>Unlock</strong> when a change is needed.</li></ol><p>To lock every order the moment you confirm it, turn on <strong>Lock Confirm Sales</strong> in the Sales settings. See <a href="./../configuration/settings.html">Settings</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Lock an order once the customer has agreed. It keeps the price and quantities safe while you deliver and invoice.</p></div><h2 id="order-status-at-a-glance" tabindex="-1">Order status at a glance <a class="header-anchor" href="#order-status-at-a-glance" aria-label="Permalink to &quot;Order status at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Where you see it</th><th>Typical value</th></tr></thead><tbody><tr><td>Customer accepts</td><td><strong>Status</strong></td><td><strong>Sales Order</strong></td></tr><tr><td>Ready to bill</td><td><strong>Invoice Status</strong></td><td><strong>To Invoice</strong></td></tr><tr><td>Goods shipped</td><td><strong>Delivery Status</strong></td><td><strong>Fully Delivered</strong></td></tr><tr><td>Bill sent</td><td><strong>Invoices</strong> tab</td><td>A row with <strong>Amount Due</strong></td></tr><tr><td>Money received</td><td><strong>Payment State</strong></td><td>Paid</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./send-and-confirm-quotation.html">Send and confirm a quotation</a></li><li><a href="./../invoicing/order-to-invoice.html">Create an invoice from an order</a></li><li><a href="./../invoicing/order-to-upsell.html">Sell more to the same customer</a></li><li><a href="./../invoicing/invoicing-policies.html">Invoicing policies</a></li><li><a href="./../../../finance/customer-invoices/create-invoice.html">Create an invoice</a></li><li><a href="./../../../finance/payments/register-payment.html">Register a payment</a></li><li><a href="./../configuration/settings.html">Settings</a></li></ul>',15))])}const f=n(l,[["render",d]]);export{v as __pageData,f as default};
